def next_recovery(task):
    """
    Determine the next recovery action based on the task state.
    - 'wait' if the task is live (lease is active).
    - 'retry' if the task is queued or failed with attempts < max_attempts.
    - 'escalate' if the task is failed and attempts >= max_attempts.
    - Raise ValueError for unknown states.
    """
    if task.get('state') == 'live':
        return 'wait'
    elif task.get('state') == 'queued':
        return 'retry'
    elif task.get('state') == 'failed':
        if task.get('attempts', 0) < task.get('max_attempts', 1):
            return 'retry'
        else:
            return 'escalate'
    else:
        raise ValueError("Unknown task state")

import recovery
import json

# Test cases for next_recovery function
def test_live_task():
    task = {"state": "live"}
    assert recovery.next_recovery(task) == "wait"

def test_queued_task():
    task = {"state": "queued"}
    assert recovery.next_recovery(task) == "retry"

def test_failed_task_within_attempts():
    task = {"state": "failed", "attempts": 2, "max_attempts": 5}
    assert recovery.next_recovery(task) == "retry"

def test_failed_task_exceeded_attempts():
    task = {"state": "failed", "attempts": 5, "max_attempts": 5}
    assert recovery.next_recovery(task) == "escalate"

def test_unknown_state():
    task = {"state": "unknown"}
    try:
        recovery.next_recovery(task)
        assert False, "Expected ValueError for unknown state"
    except ValueError:
        pass

if __name__ == "__main__":
    test_live_task()
    test_queued_task()
    test_failed_task_within_attempts()
    test_failed_task_exceeded_attempts()
    test_unknown_state()
